//! Signed observations and durable summaries, isolated from adjudication.
use super::*;
fn work_integer(v:&Value,k:&str)->Result<u64>{let s=text(v,k)?;if s.is_empty()||s.len()>20||s.len()>1&&s.starts_with('0')||!s.bytes().all(|b|b.is_ascii_digit()){return Err("INVALID_INPUT: canonical work decimal".into());}s.parse().map_err(|_|"INVALID_INPUT: work integer bound".into())}
impl Authority {
    pub(super) fn product_identity(&self,db:&Connection)->Result<Value>{
        let g:Value=parse(sql(db.query_row("SELECT spec_json FROM goal_specs JOIN goal_plan_progress USING(goal_id) WHERE campaign_id=? ORDER BY plan_index LIMIT 1",[&self.config.campaign_id],|r|r.get(0)))?)?;
        Ok(json!({"environment":"development","modelIdentity":{"graphRoot":g["graphRoot"],"modelRoot":g["modelRoot"],"modelDataRoot":g["modelDataRoot"],"registryRoot":g["registryRoot"],"parameterProfileHash":g["parameterProfileHash"]},"serviceCapabilities":{"completeReplay":true,"signedTelemetry":true,"roundHistory":true,"payment":false,"rewards":false},"payment":false,"rewards":false}))
    }
    pub(super) fn supply(&self,db:&Connection)->Result<Value>{
        let pending:u64=sql(db.query_row("SELECT COUNT(*) FROM goal_plan_progress WHERE campaign_id=? AND state='PENDING'",[&self.config.campaign_id],|r|r.get(0)))?;
        let active:u64=sql(db.query_row("SELECT COUNT(*) FROM target_rounds WHERE campaign_id=? AND status IN ('OPEN','VERIFYING')",[&self.config.campaign_id],|r|r.get(0)))?;
        let plan:Option<(u64,String)>=sql(db.query_row("SELECT revision,plan_hash FROM goal_plan_revisions WHERE campaign_id=? ORDER BY revision DESC LIMIT 1",[&self.config.campaign_id],|r|Ok((r.get(0)?,r.get(1)?))).optional())?;
        let reserved:u64=sql(db.query_row("SELECT COALESCE(SUM(bytes),0) FROM candidate_artifacts WHERE status!='CLEANED'",[],|r|r.get(0)))?;
        Ok(json!({"schema":"flypow-goal-supply-v1","status":if pending==0{"exhausted"}else if pending<=active{"last-goal"}else{"available"},"solvedGoals":sql(db.query_row("SELECT COUNT(*) FROM goal_plan_progress WHERE campaign_id=? AND state='SOLVED'",[&self.config.campaign_id],|r|r.get::<_,u64>(0)))?,"deferredGoals":sql(db.query_row("SELECT COUNT(*) FROM goal_schedule WHERE campaign_id=? AND eligible_at>?",params![self.config.campaign_id,now()],|r|r.get::<_,u64>(0)))?,"pendingGoals":pending,"remainingUnopenedGoals":pending.saturating_sub(active),"planRevision":plan.as_ref().map(|p|p.0).unwrap_or(0),"planHash":plan.map(|p|p.1),"privateArchiveReservedBytes":reserved,"privateArchiveCapacityBytes":self.config.max_private_bytes,"appendRequires":"admin signature and real calibration; solved goals never repeated","difficultyFeedbackMinimum":16}))
    }
    pub fn report_work(&self,r:&SignedRequest,at:u64)->Result<Value>{
        r.authenticate("session-work-report")?;let v=&r.payload;let sid=text(v,"sessionId")?;let phase=text(v,"phase")?;let seq=num(v,"sequence")?;let produced=num(v,"producedAt")?;
        if v["schema"]!="flypow-session-work-report-v1"||v["networkId"]!=self.config.network_id||v["authorityId"]!=self.authority_id||v["campaignId"]!=self.config.campaign_id||v["roundId"]!=r.round_id||sid.len()<8||sid.len()>128||!sid.bytes().all(|b|b.is_ascii_alphanumeric()||b"-_".contains(&b))||seq==0||seq>9_007_199_254_740_991||!["computing","searching","waiting","saving","paused","ended","offline","domain-exhausted"].contains(&phase.as_str()){return Err("INVALID_INPUT: work report identity/stage".into());}
        let neurons=work_integer(v,"neuronUpdates")?;let synapses=work_integer(v,"synapseAdditions")?;let digest=id("session-work-report",v)?;
        let mut db=self.lock()?;let tx=sql(db.transaction_with_behavior(TransactionBehavior::Immediate))?;let at=self.check_clock(&tx,at)?;
        if produced<at.saturating_sub(60)*1000||produced>(at+15)*1000{return Err("INVALID_INPUT: expired work report".into());}
        if !r.round_id.is_empty(){let n:u64=sql(tx.query_row("SELECT COUNT(*) FROM target_rounds WHERE campaign_id=? AND round_id=?",params![self.config.campaign_id,r.round_id],|r|r.get(0)))?;if n!=1{return Err("INVALID_INPUT: telemetry round".into());}}
        let old:Option<(u64,u64,u64,String,String,String)>=sql(tx.query_row("SELECT sequence,produced_at,last_seen,neurons,synapses,request_hash FROM work_sessions WHERE miner_id=? AND session_id=?",params![r.public_key,sid],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?,r.get(5)?))).optional())?;
        if let Some((previous,created,seen,n,s,h))=&old {
            if seq==*previous&&digest==*h{return self.signed("work-report-receipt",json!({"sessionId":sid,"sequence":seq,"receivedAt":seen,"expiresAt":seen+45,"duplicate":true,"usedForRewardsOrDifficulty":false}));}
            if seq<=*previous||produced<*created{return Err("CONFLICT: telemetry replay/sequence regression".into());}
            let previous_n=n.parse::<u64>().map_err(|_|"stored work integer")?;let previous_s=s.parse::<u64>().map_err(|_|"stored work integer")?;
            if neurons<previous_n||synapses<previous_s{return Err("CONFLICT: counter reset requires a new session identity".into());}
            let elapsed=at.saturating_sub(*seen);if elapsed<2{return Err("BACKPRESSURE: telemetry interval is at least 2 seconds".into());}
            if neurons-previous_n>100_000_000_000*elapsed.min(3600)||synapses-previous_s>1_000_000_000_000*elapsed.min(3600){return Err("INVALID_INPUT: anomalous self-reported rate".into());}
            if elapsed<=45 {sql(tx.execute("INSERT INTO work_samples(miner_id,session_id,from_at,to_at,neurons,synapses) VALUES(?,?,?,?,?,?)",params![r.public_key,sid,seen,at,(neurons-previous_n).to_string(),(synapses-previous_s).to_string()]))?;}
        }else{let active:u64=sql(tx.query_row("SELECT COUNT(*) FROM work_sessions WHERE last_seen>?",[at.saturating_sub(45)],|r|r.get(0)))?;if active>=2048{return Err("BACKPRESSURE: bounded telemetry sessions".into());}}
        sql(tx.execute("INSERT INTO work_sessions VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(miner_id,session_id) DO UPDATE SET round_id=excluded.round_id,sequence=excluded.sequence,produced_at=excluded.produced_at,last_seen=excluded.last_seen,phase=excluded.phase,neurons=excluded.neurons,synapses=excluded.synapses,request_hash=excluded.request_hash",params![r.public_key,sid,self.config.campaign_id,r.round_id,seq,produced,at,phase,neurons.to_string(),synapses.to_string(),digest]))?;
        sql(tx.execute("INSERT INTO target_sessions VALUES(?,?,?,?,?) ON CONFLICT(miner_id,session_id) DO UPDATE SET round_id=excluded.round_id,phase=excluded.phase,last_seen=excluded.last_seen",params![r.public_key,sid,r.round_id,phase,at]))?;
        sql(tx.execute("DELETE FROM work_samples WHERE to_at<?",[at.saturating_sub(300)]))?;sql(tx.execute("DELETE FROM work_sessions WHERE last_seen<?",[at.saturating_sub(86400)]))?;sql(tx.execute("DELETE FROM target_sessions WHERE last_seen<?",[at.saturating_sub(86400)]))?;
        let receipt=self.signed("work-report-receipt",json!({"sessionId":sid,"sequence":seq,"receivedAt":at,"expiresAt":at+45,"duplicate":false,"source":"signed client cumulative counters, not verified work","usedForRewardsOrDifficulty":false}))?;sql(tx.commit())?;Ok(receipt)
    }
    pub fn statistics_at(&self,at:u64)->Result<Value>{
        let db=self.lock()?;let from=at.saturating_sub(30);let active:u64=sql(db.query_row("SELECT COUNT(DISTINCT miner_id) FROM target_sessions WHERE last_seen>=? AND phase IN ('searching','computing')",[at.saturating_sub(45)],|r|r.get(0)))?;
        let reports:u64=sql(db.query_row("SELECT COUNT(*) FROM work_sessions WHERE campaign_id=? AND last_seen>=?",params![self.config.campaign_id,at.saturating_sub(45)],|r|r.get(0)))?;
        let updated:Option<u64>=sql(db.query_row("SELECT MAX(last_seen) FROM work_sessions WHERE campaign_id=?",[&self.config.campaign_id],|r|r.get(0)))?;
        let mut query=sql(db.prepare("SELECT from_at,to_at,s.neurons,s.synapses FROM work_samples s JOIN work_sessions w USING(miner_id,session_id) WHERE w.campaign_id=? AND w.last_seen>=? AND to_at>? AND from_at<?"))?;
        let rows=sql(query.query_map(params![self.config.campaign_id,at.saturating_sub(45),from,at],|r|Ok((r.get::<_,u64>(0)?,r.get::<_,u64>(1)?,r.get::<_,String>(2)?,r.get::<_,String>(3)?))))?.collect::<rusqlite::Result<Vec<_>>>().map_err(|e|e.to_string())?;
        let mut neurons=0u128;let mut synapses=0u128;let mut measured=0u64;
        for (start,end,n,s) in rows {let overlap=end.min(at).saturating_sub(start.max(from));let duration=end.saturating_sub(start);if duration>0{neurons+=n.parse::<u128>().map_err(|_|"work count")?*overlap as u128/duration as u128;synapses+=s.parse::<u128>().map_err(|_|"work count")?*overlap as u128/duration as u128;measured+=1;}}
        let status=if reports==0{if updated.is_some(){"stale"}else{"unavailable"}}else if measured==0{"sampling"}else{"measured"};
        let source="signed client self-report; signatures establish identity, not work truth; excluded from difficulty and rewards";
        let metric=|work:String|json!({"status":status,"work":if status=="measured"{Some(work)}else{None},"windowMs":30000,"from":from,"asOf":at,"updatedAt":updated,"expiresAt":updated.map(|t|t+45),"source":source,"coverage":{"reportedSessions":reports,"activeSignedIdentities":active,"completeSearchCoverage":false},"reason":if status=="measured"{Value::Null}else{json!(status)}});
        let queue:u64=sql(db.query_row("SELECT COUNT(*) FROM candidate_claims c JOIN target_rounds r USING(round_id) WHERE campaign_id=? AND ((c.status='COMMITTED' AND c.reveal_deadline>=?) OR (c.status='REVEALED' AND c.verification_deadline>=?))",params![self.config.campaign_id,at,at],|r|r.get(0)))?;
        // A third assignment can remain in the audit trail after quorum made
        // its claim terminal. Only jobs that can still be leased are queued.
        let replay_queue:u64=sql(db.query_row("SELECT COUNT(*) FROM verification_jobs j JOIN candidate_claims c USING(claim_id) JOIN target_rounds r USING(round_id) WHERE campaign_id=? AND c.status='REVEALED' AND c.verification_deadline>=? AND j.status IN ('PENDING','LEASED')",params![self.config.campaign_id,at],|r|r.get(0)))?;
        let winners:u64=sql(db.query_row("SELECT COUNT(*) FROM round_winners JOIN target_rounds USING(round_id) WHERE campaign_id=?",[&self.config.campaign_id],|r|r.get(0)))?;
        let valid:u64=sql(db.query_row("SELECT COUNT(*) FROM candidate_claims JOIN target_rounds USING(round_id) WHERE campaign_id=? AND candidate_claims.status='VALID' AND received_at>=?",params![self.config.campaign_id,from],|r|r.get(0)))?;
        let replay:u64=sql(db.query_row("SELECT COUNT(*) FROM verification_votes JOIN candidate_claims USING(claim_id) JOIN target_rounds USING(round_id) WHERE campaign_id=? AND verification_votes.received_at>=?",params![self.config.campaign_id,from],|r|r.get(0)))?;
        let mut candidates=std::collections::BTreeSet::new();let mut backgrounds=std::collections::BTreeSet::new();
        let mut q=sql(db.prepare("SELECT manifest_json FROM candidate_reveals JOIN candidate_claims USING(claim_id) JOIN target_rounds USING(round_id) WHERE campaign_id=? AND candidate_claims.status='VALID' AND candidate_claims.received_at>=?"))?;
        for raw in sql(q.query_map(params![self.config.campaign_id,from],|r|r.get::<_,String>(0)))?{let m=parse(raw.map_err(|e|e.to_string())?)?;candidates.insert(text(&m,"candidateId")?);for t in m["trials"].as_array().ok_or("trial manifests")?{backgrounds.insert((text(&m,"candidateId")?,text(t,"trialId")?));}}
        let count=|n:u64|json!({"value":n,"windowMs":30000,"from":from,"asOf":at,"expiresAt":at+15,"status":"measured","source":"persistent SQLite claims/manifests/replay reports","coverage":"all admitted records in this authority campaign"});
        let controller=parse(sql(db.query_row("SELECT controller_json FROM difficulty_snapshots WHERE campaign_id=?",[&self.config.campaign_id],|r|r.get(0)))?)?;
        let sequence:u64=sql(db.query_row("SELECT COALESCE(MAX(event_sequence),0) FROM protocol_events",[],|r|r.get(0)))?;
        self.signed("network-stats",json!({"schema":"flypow-network-statistics-v1","networkId":self.config.network_id,"authorityId":self.authority_id,"campaignId":self.config.campaign_id,"asOf":at,"measuredAt":at,"expiresAt":at+15,"eventSequence":sequence,"activeSignedIdentities":active,"pendingClaims":queue,"verificationQueue":replay_queue,"confirmedRounds":winners,"totalHashRate":null,"networkSearchEstimate":"NO_SEARCH_WORK_RECEIPTS","metrics":{"selfReportedNeuronUpdates":metric(neurons.to_string()),"selfReportedSynapseAdditions":metric(synapses.to_string()),"validClaims":count(valid),"uniqueCandidates":count(candidates.len() as u64),"completeBackgrounds":count(backgrounds.len() as u64),"replayReports":count(replay)},"supply":self.supply(&db)?,"difficultyController":controller,"stateSource":"persistent SQLite; not a decentralized operator count"}))
    }
    pub fn round_history(&self,before:u64,limit:u64)->Result<Value>{
        let db=self.lock()?;let limit=limit.clamp(1,100);let mut q=sql(db.prepare("SELECT r.descriptor_json,r.status,w.winner_json FROM target_rounds r LEFT JOIN round_winners w USING(round_id) WHERE r.campaign_id=? AND (?=0 OR r.sequence<?) ORDER BY r.sequence DESC LIMIT ?"))?;
        let rows=sql(q.query_map(params![self.config.campaign_id,before,before,limit],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?,r.get::<_,Option<String>>(2)?))))?.map(|x|{let(r,status,w)=x.map_err(|e|e.to_string())?;let r=parse(r)?;Ok(json!({"roundId":r["roundId"],"roundSequence":r["pre"]["roundSequence"],"goalId":r["pre"]["goalId"],"openedAt":r["pre"]["openedAt"],"difficultyMicros":r["pre"]["difficultyMicros"],"status":status,"winner":w.map(parse).transpose()?}))}).collect::<Result<Vec<_>>>()?;
        let at=now();self.signed("round-history",json!({"schema":"flypow-round-history-v1","networkId":self.config.network_id,"authorityId":self.authority_id,"campaignId":self.config.campaign_id,"asOf":at,"expiresAt":at+15,"nextBefore":if rows.len() as u64==limit{rows.last().map(|r|r["roundSequence"].clone())}else{None},"rounds":rows,"source":"persistent target_rounds and round_winners; SSE is incremental only"}))
    }
}
